import { Component, EventEmitter, Input, Output } from '@angular/core';
import { downloadList } from '../../../../interfaces/download.interface';
import { ButtonComponent } from '../../../../../shared/components/button/button.component';
import { IconComponent } from '../../../../../shared/components/icon/icon.component';
import { DownloadService } from '../../../../services/download/download.service';
import { toolEvents } from '../../../../../pdf/interfaces/pdf.interface';
import { MatMenuModule } from '@angular/material/menu';
import { TostbarService } from '../../../../../core/services/tost/tostbar.service';

@Component({
  selector: 'download-action',
  standalone: true,
  imports: [IconComponent, ButtonComponent, MatMenuModule],
  templateUrl: './action.component.html',
  styleUrl: './action.component.scss'
})
export class ActionComponent {
  @Input() x: downloadList;
  @Output() onEvent = new EventEmitter<toolEvents>();

  isDownloadLoading: boolean = false;
  isDeleteLoading: boolean = false;
  constructor(private readonly downloadService: DownloadService, private readonly toast: TostbarService) { }


  async downloadFile() {
    debugger;
    this.isDownloadLoading = true
    const url = await this.downloadService.getDonwloadURL(this.x.nDPid);
    this.isDownloadLoading = false;
    if (url)
      window.open(url, '_blank');
  }

  async copy() {
    try {
      const url = await this.downloadService.getDonwloadURL(this.x.nDPid);
      if (url) {
        await navigator.clipboard.writeText(url);
        this.toast.success('Download URL copied to clipboard!');
      }
    } catch (error) {
      // Optionally, handle error (e.g., show a message)
    }
  }

  async retryDownload() {
    this.x.cStatus = 'R';
    this.isDownloadLoading = true
    await this.downloadService.retryJob(this.x.nDPid);
    this.isDownloadLoading = false;
  }


  async deleteFile() {
    this.isDeleteLoading = true;
    try {
      const res = await this.downloadService.deleteJob(this.x.nDPid);
      if (res?.msg == 1) {
        this.onEvent.emit({ event: 'DELETE', data: { nDPid: this.x.nDPid } });
      }
    } catch (error) {
    }
    this.isDeleteLoading = false;
  }

}
