import { Component, ChangeDetectorRef } from '@angular/core';
import { MatSelectModule } from '@angular/material/select';
import { MatFormFieldModule } from '@angular/material/form-field';
import { IconComponent } from '../../../../../shared/components/icon/icon.component';
import { ButtonComponent } from '../../../../../shared/components/button/button.component';
import { CommonModule } from '@angular/common';
import { EmptyComponent } from '../../../../../shared/components/empty/empty.component';
import { SkeletonComponent } from '../../../../../shared/components/skeleton/skeleton.component';
// import { ExportService } from '../../../services/export/export.service'; // Removed
import { FormsModule } from '@angular/forms';
import { CdkVirtualScrollViewport, ScrollingModule } from '@angular/cdk/scrolling';
import { downloadList, downloadMessage, downloadMessageBody } from '../../../../interfaces/download.interface';
import { DownloadService } from '../../../../services/download/download.service';
import { StatusComponent } from '../status/status.component';
import { ActionComponent } from '../action/action.component';
import { ProcessListComponent } from '../process-list/process-list.component';
import { BytesPipe } from '../../../../../shared/pips/bytes/bytes.pipe';
import { NgScrollReached } from 'ngx-scrollbar/reached-event';
import { NgScrollbarModule } from 'ngx-scrollbar';
import { SocketService } from '../../../../../core/services/socket/socket.service';
import { Subscription } from 'rxjs';
import { ActivatedRoute } from '@angular/router';
import { HeaderService } from '../../../../../core/services/header/header.service';
import { toolEvents } from '../../../../../pdf/interfaces/pdf.interface';
import { UserPermissionService } from '../../../../../shared/services/user-permission/user-permission.service';
@Component({
  selector: 'app-download',
  standalone: true,
  imports: [CommonModule, FormsModule, SkeletonComponent, MatSelectModule, MatFormFieldModule,
    ButtonComponent, EmptyComponent, ScrollingModule,
    StatusComponent, ActionComponent, ProcessListComponent, BytesPipe,
    NgScrollbarModule, NgScrollReached],
  templateUrl: './download.component.html',
  styleUrl: './download.component.scss'
})
export class DownloadComponent {



  cSortBy: 'N' | 'O' = 'N';
  loading: boolean = false;
  downloadList: downloadList[] = [];
  nCaseid: string; // '007a3614-ac77-40e4-bad1-4962b6571c58';
  PageNumber: number = 1;
  isNoMoreData: boolean = false;
  socketSubscription: Subscription;

  isInidvidualLoading: boolean = false;
  constructor(private readonly downloadService: DownloadService, private readonly socketService: SocketService, private route: ActivatedRoute,
    private hs: HeaderService, private userPermissions: UserPermissionService
  ) {
    var params = this.route.snapshot.params;
    params = JSON.parse(atob(params["id"]));
    this.nCaseid = params && params["id"] ? params["id"] : null;
    this.hs.nCaseid = this.nCaseid
    userPermissions.userPermissionList(this.nCaseid);

  }

  ngAfterViewInit() {
    this.fetchDownloadList();
    this.socketSubscription = this.socketService.downloadMessage().subscribe((msg: downloadMessage) => {
      if (['DOWNLOAD-STATUS', 'DOWNLOAD-PROGRESS'].includes(msg.event)) {
        const downloadJob = this.downloadList.find(job => job.nDPid === msg.data?.nDPid);
        if (downloadJob) {
          this.updateDetail(downloadJob, msg.data);
        } else {
          if (msg.data?.nDPid) {
            if (this.isInidvidualLoading) return;
            this.fetchIndividualDownload(msg.data?.nDPid);
          }
        }
      }

    })
  }

  ngOnInit() {



  }
  updateDetail(downloadJob: downloadList, body: downloadMessageBody) {

    if (body?.cStatus)
      downloadJob.cStatus = body.cStatus; // Update status to active
    if (body?.dStartDt)
      downloadJob.dStartDt = body.dStartDt; // Update start date
    downloadJob.lastUpdated = new Date().toISOString(); // Update last updated time

    if (body?.completedParts) {
      downloadJob.completedParts = body.completedParts; // Update completed parts
    }
    if (body?.totalParts) {
      downloadJob.totalParts = body.totalParts; // Update total parts
    }
    if (body?.actionStatus) {
      downloadJob.actionStatus = body.actionStatus; // Update action status
    }
    downloadJob.progress = this.calculateProgress(downloadJob); // Recalculate progress

    if (body?.MergeCompletedParts) {
      downloadJob.MergeCompletedParts = body.MergeCompletedParts; // Update completed parts
    }
    if (body?.MergeTotalParts) {
      downloadJob.MergeTotalParts = body.MergeTotalParts; // Update total parts
    }

    if (body?.totalSize) {
      downloadJob.totalSize = body.totalSize; // Update total parts
    }

    downloadJob.mergeProgress = this.calculateMergeProgress(downloadJob); // Recalculate progress
  }




  filterChanged() {
    this.PageNumber = 1;
    this.downloadList = [];
    this.isNoMoreData = false;
    this.fetchDownloadList();
  }


  async fetchIndividualDownload(nDPid: string) {
    this.isInidvidualLoading = true;
    const res = await this.downloadService.getDownloadJobs(this.nCaseid, 1, this.cSortBy, nDPid);
    this.isInidvidualLoading = false;
    if (res?.length) {
      res.map((a: downloadList) => a.progress = this.calculateProgress(a));
      res.map((a: downloadList) => a.mergeProgress = this.calculateMergeProgress(a));
      if (nDPid) {
        const existingIndex = this.downloadList.findIndex(x => x.nDPid == nDPid);
        if (existingIndex == -1) {
          this.downloadList.unshift(res[0]); // Add new job
        }
      }
    }
  }


  async fetchDownloadList() {
    this.loading = true;
    const res = await this.downloadService.getDownloadJobs(this.nCaseid, this.PageNumber, this.cSortBy);
    if (res?.length) {
      res.map((a: downloadList) => a.progress = this.calculateProgress(a));
      res.map((a: downloadList) => a.mergeProgress = this.calculateMergeProgress(a));
      this.downloadList.push(...res);
      this.PageNumber++;
      this.isNoMoreData = false;
    } else {
      this.isNoMoreData = true;
    }
    this.loading = false;
  }



  calculateProgress(x: downloadList) {
    if (x.totalParts == 0) return 0;
    if (x.completedParts == 0) return 0;
    if (x.completedParts >= x.totalParts) return 100;
    return Math.round((x.completedParts / x.totalParts) * 100);
  }


  calculateMergeProgress(x: downloadList) {
    if (x.MergeTotalParts == 0) return 0;
    if (x.MergeCompletedParts == 0) return 0;
    if (x.MergeCompletedParts >= x.MergeTotalParts) return 100;
    return Math.round((x.MergeCompletedParts / x.MergeTotalParts) * 100);
  }

  onReachEnd() {
    if (this.isNoMoreData || this.loading) return;
    this.fetchDownloadList();
  }

  ngOnDestroy(): void {
    this.PageNumber = 1;
    this.downloadList = [];
    this.isNoMoreData = false;
    this.socketSubscription?.unsubscribe();
  }



  ActionEvent(event: toolEvents, index: number) {
    if (event.event == 'DELETE') {
      this.downloadList.splice(index, 1);

    }
  }

}
